import java.util.*;
public class FiveDayWeekTest {
  static Map<String,Object> fixture(){Map<String,Object> x=new HashMap<>();x.put("classes",List.of(Map.of("name","9/1","shift","morning")));x.put("teachers",List.of(Map.of("name","Lan")));x.put("assignments",List.of(Map.of("className","9/1","teacher","Lan","subject","Toán","periods",4)));x.put("events",List.of());x.put("schedule",List.of(Map.of("className","9/1","shift","morning","day",5,"period",1,"teacher","Lan","subject","Toán","locked",true)));return x;}
  public static void main(String[] args){Map<String,Object> data=fixture(),result=new Main.Scheduler(data).run();if(!Boolean.TRUE.equals(result.get("ok")))throw new AssertionError(result);List<?> schedule=(List<?>)result.get("schedule");if(schedule.size()!=4)throw new AssertionError("A Saturday lesson must return to the pool");for(Object item:schedule){Map<?,?> lesson=(Map<?,?>)item;if((Integer)lesson.get("day")>4)throw new AssertionError("Saturday generated");if(Boolean.TRUE.equals(lesson.get("locked")))throw new AssertionError("Saturday lock should not be retained");}data.put("events",List.of(Map.of("name","Sinh hoạt","shift","morning","day",5,"period",5)));try{new Main.Scheduler(data).run();throw new AssertionError("Saturday fixed activity accepted");}catch(IllegalArgumentException expected){}System.out.println("Saturday locks are removed; schedules use Monday to Friday only.");}
}
